-- Step 3 — 寄賣（consignment）schema
--
-- 修正版（v2）：對齊實際 DB 型別。原本版本假設 users 有 id 欄位、
--   product/transaction 用 int，跑起來 42703 錯。實際上：
--   - users PK 是 line_id (text)，沒有 numeric id
--   - products.id / transaction.id 是 bigint (GENERATED BY DEFAULT AS IDENTITY)
--
-- 設計決策（詳見 CONSIGNOR_ROADMAP.md）：
-- 1. 寄賣主鍵：consignor_line_id TEXT REFERENCES users(line_id)
--    → 寄賣者必然是 LINE user（收上架/結算/審核通知）
-- 2. commission_rate 硬編在 worker 程式，不放 DB
-- 3. transaction_items 只 snapshot「當時的寄賣主」consignor_line_id
--    → 商品之後轉手時歷史帳不會被追改
-- 4. transaction_items / payouts 的 PK 用 BIGSERIAL（每筆結帳 N 行，長期累積可能破 int）

-- 商品所有權
ALTER TABLE products
    ADD COLUMN IF NOT EXISTS consignor_line_id TEXT REFERENCES users(line_id);
CREATE INDEX IF NOT EXISTS products_consignor_idx ON products(consignor_line_id);

-- 交易明細（每筆結帳 → N 筆 line item）
--
-- 注意：product_id / consignor_line_id 是「歷史快照」，故意不設 FK。
-- 商品被刪、寄賣者離開系統時，歷史帳仍應保留原本的 id 值（就算對應 row 已消失）。
-- transaction_id 有 FK + CASCADE — 刪交易時明細跟著走是合理的。
CREATE TABLE IF NOT EXISTS transaction_items (
  id BIGSERIAL PRIMARY KEY,
  transaction_id BIGINT REFERENCES transaction(id) ON DELETE CASCADE,
  product_id BIGINT,          -- snapshot: 可能對應到已被刪除的 product
  quantity INT NOT NULL,
  unit_price INT NOT NULL,
  consignor_line_id TEXT      -- snapshot: 可能對應到已被刪除的 user
);
CREATE INDEX IF NOT EXISTS transaction_items_tx_idx ON transaction_items(transaction_id);
CREATE INDEX IF NOT EXISTS transaction_items_consignor_idx ON transaction_items(consignor_line_id);

-- 分潤結算（任意 date range）
CREATE TABLE IF NOT EXISTS payouts (
  id BIGSERIAL PRIMARY KEY,
  consignor_line_id TEXT REFERENCES users(line_id),
  period_start DATE NOT NULL,
  period_end DATE NOT NULL,
  gross_amount INT NOT NULL,
  commission_amount INT NOT NULL,
  net_payout INT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',   -- pending / paid
  paid_at TIMESTAMP
);
CREATE INDEX IF NOT EXISTS payouts_consignor_idx ON payouts(consignor_line_id);
CREATE INDEX IF NOT EXISTS payouts_period_idx ON payouts(period_start, period_end);
